mapper.select:
select fresh.id, fresh.picture_address, fresh.fresh_name, fresh.category_id, category.category_name, fresh.feature, fresh.description, fresh.prices, fresh.promotion_price, fresh.repertory, fresh.sum_repertory, fresh.is_recommend from fresh left join category on fresh.category_id = category.id where fresh.is_deleted = 0
and fresh.fresh_name like '%${freshName}%'
AND category_id = #{categoryId}
and fresh.is_recommend = #{recommend}
order by fresh.update_time desc

mapper.update:
UPDATE fresh
SET repertory = repertory - #{count},
    version = version + 1
WHERE id = #{freshId}
  AND repertory >= #{count}
  AND is_deleted = 0

mapper.select:
SELECT fresh.*, category.id, category.category_name FROM fresh LEFT JOIN category ON fresh.category_id = category.id
fresh.is_deleted = 0
AND fresh.fresh_name LIKE CONCAT('%', #{freshName}, '%')
AND fresh.category_id = #{categoryId}
AND fresh.is_recommend = #{recommend}
ORDER BY fresh.id ASC

SELECT category_id FROM fresh
WHERE id IN

    #{id}
